import{d as h,C as n,o as g,c as d,j as a,a as e,E as o,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"中庸·第7章","description":"《中庸》第 7 章——两种「予知」：不知避祸，与能择而不能守。孔子说，这都算不上真知。","frontmatter":{"title":"中庸·第7章","description":"《中庸》第 7 章——两种「予知」：不知避祸，与能择而不能守。孔子说，这都算不上真知。","category":"guide","aliases":["第7章","中庸第7章","予知"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-07.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-07.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/zhongyong/chapter-07.md"},f=h({...m,setup(p){const t=[{id:"bubi",label:"人皆曰予知 · 莫之知辟",showLabel:!0,sentences:[["子曰：“人皆曰‘",{text:"予知",glossary:"yuzhi"},"’，驱而纳诸",{text:"罟擭陷阱",glossary:"guhuoxianjing"},"之中，而莫之知",{text:"辟",glossary:"bi"},"也。"]],note:"孔子讽刺那些自诩聪明的人：「人皆曰『予知』」，人人都说自己聪明；可一旦被驱赶进网罗陷阱（罟擭陷阱）之中，却「莫之知辟」——不知躲避。这是「知」之小与假。"},{id:"nengshou",label:"择乎中庸 · 不能期月守",showLabel:!0,sentences:[["人皆曰‘予知’，",{text:"择",glossary:"ze"},"乎中庸而不能",{text:"期月",glossary:"qiyue"},{text:"守",glossary:"shou"},"也。”"]],note:"再进一层：这些自称聪明的人，「择乎中庸而不能期月守也」——纵然选中了中庸，也守不满一个月（期月＝满一月）。择而不能守，正是不明之实。"}],r=[{id:"yuzhi",term:"予知",pinyin:"yú zhì",meaning:"自以为聪明。予：我；知：此处通「智」，读 zhì。"},{id:"guhuoxianjing",term:"罟擭陷阱",pinyin:"gǔ huò xiàn jǐng",meaning:"罟是网，擭是机槛，陷阱是坑坎——都是掩取禽兽之物，此处喻祸患。"},{id:"bi",term:"辟",pinyin:"bì",meaning:"同「避」，躲避。"},{id:"ze",term:"择",pinyin:"zé",meaning:"辨别而选择。「择乎中庸」，即上章好问用中之事。"},{id:"qiyue",term:"期月",pinyin:"jī yuè",meaning:"满一个月。期：读 jī，指一周年或一整月。"},{id:"shou",term:"守",pinyin:"shǒu",meaning:"持守、守得住。朱注：「言知祸而不知辟，以况能择而不能守，皆不得为知也。」"}];return(c,i)=>{const l=n("DaoTextReading"),s=n("DaoKeywordCards");return g(),d("div",null,[i[0]||(i[0]=a("h1",{id:"中庸·第7章",tabindex:"-1"},[e("中庸·第7章 "),a("a",{class:"header-anchor",href:"#中庸·第7章","aria-label":'Permalink to "中庸·第7章"'},"​")],-1)),i[1]||(i[1]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[e("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),i[2]||(i[2]=a("p",null,[e("本章说两种「自以为知」：一是"),a("strong",null,"不知避祸"),e("，一是"),a("strong",null,"能择而不能守"),e("。孔子说，这两种都算不上真知。默认竹简沉浸通读；切「经典阅读」可点生词。")],-1)),o(l,{colophon:"予知 · 择而不能守",tone:"ink",sections:t,glossary:r,"default-mode":"slips","aria-label":"中庸·第7章 原文"}),i[3]||(i[3]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[e("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),o(s,{items:[{term:"予知",pinyin:["yú","zhì"],meaning:"自以为聪明。予：我；知：通「智」。"},{term:"罟擭陷阱",pinyin:["gǔ","huò","xiàn","jǐng"],meaning:"罟是网，擭是机槛，陷阱是坑坎——皆掩取禽兽之物，喻祸患。"},{term:"辟",pinyin:["bì"],meaning:"同「避」，躲避。"},{term:"期月",pinyin:["jī","yuè"],meaning:"满一个月。期：读 jī。"},{term:"守",pinyin:["shǒu"],meaning:"持守。朱注：「能择而不能守，皆不得为知也。」"}]}),i[4]||(i[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>人皆曰予知 · 莫之知辟</strong>：人人都说「我很聪明」，可被赶进网罗陷阱之中，却不知道躲避。</p><p><strong>择乎中庸 · 不能期月守</strong>：人人都说「我很聪明」，可是选择了中庸，连一个月也守不住。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第七章说两种「自以为知」：一种<strong>不知避祸</strong>（被赶进陷阱还不知道躲），一种<strong>能择而不能守</strong>（选了中庸，连一个月也守不住）。</p><p>前一种是「看不见」，后一种是「守不住」。孔子说，这两样都算不上真知——朱注：「皆不得为知也。」</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它给「守」立了一个极低的门槛</strong>：「期月」（一个月）。门槛越低越见真章——连一个月都守不住，说明问题不在难度。</li><li><strong>它把两句并列，指出同一个病</strong>：朱注说「言知祸而不知辟，以况能择而不能守」——<strong>知道却做不到</strong>，这两处是同一个症候。</li><li><strong>承上章而反照</strong>：第六章舜「择乎中庸」而能「用其中于民」，第七章紧接着说多数人「择而不能守」。同类对照，正见舜之所以为舜。</li><li><strong>真知的判准被改写</strong>：不在「说得出来」，而在「守得住」。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>自问「守了多久」</strong>：我最近「择」过什么？到今天为止，还守着吗？</li><li><strong>防「予知」</strong>：自以为懂，是停止用功的开始。</li><li><strong>用一个月做实验</strong>：把「期月」当成一个可执行的最小验收期。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：人人都说自己聪明——可是被赶进陷阱里，还不知道躲；人人都说自己聪明——可是选定了中庸，连一个月也守不住。</p><p>两句话一个意思：<strong>问题不在「知不知道」，在「做不做、守不守」</strong>。一个月是极低的标准，连它都过不去，就别再拿「我知道」当答案了。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「期月」只有一个月——用这把尺子量我最近的一件「立志」，结果如何？</li><li>「知祸而不知辟」——我有没有明知不好、却仍在做的事？</li><li>「予知」——我在哪件事上最容易「自以为懂」？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-06">中庸·第6章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-08">中庸·第8章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',21))])}}});export{b as __pageData,f as default};
